// Webview GUI files compiled into the plugin. The definitions are generated by
// web/scripts/build-wclap-gui.mjs so the GUI works without host filesystem access.
#pragma once
#include <cstdint>

namespace helm {
struct EmbeddedResource {
  const char* path;  // absolute, e.g. "/index.html"
  const char* mime;
  const unsigned char* data;
  uint32_t size;
};
extern const EmbeddedResource webviewResources[];
extern const uint32_t webviewResourceCount;
}  // namespace helm
